ALTER TABLE "Usuario" ADD COLUMN "pontos" INTEGER NOT NULL DEFAULT 0;
ALTER TABLE "Pedido" ADD COLUMN "pontosGerados" INTEGER NOT NULL DEFAULT 0;
ALTER TABLE "Pedido" ADD COLUMN "pontosResgatados" INTEGER NOT NULL DEFAULT 0;
ALTER TABLE "Pedido" ADD COLUMN "desconto" DECIMAL NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS "Promocao" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "nome" TEXT NOT NULL, "descricao" TEXT, "percentual" INTEGER NOT NULL, "inicio" DATETIME NOT NULL, "fim" DATETIME NOT NULL, "ativa" BOOLEAN NOT NULL DEFAULT true, "unidadeId" INTEGER, "produtoId" INTEGER, "criadoEm" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Promocao_unidadeId_fkey" FOREIGN KEY ("unidadeId") REFERENCES "Unidade"("id"), CONSTRAINT "Promocao_produtoId_fkey" FOREIGN KEY ("produtoId") REFERENCES "Produto"("id"));
CREATE TABLE IF NOT EXISTS "MovimentoPontos" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "usuarioId" INTEGER NOT NULL, "pedidoId" INTEGER, "tipo" TEXT NOT NULL, "pontos" INTEGER NOT NULL, "descricao" TEXT NOT NULL, "criadoEm" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "MovimentoPontos_usuarioId_fkey" FOREIGN KEY ("usuarioId") REFERENCES "Usuario"("id"), CONSTRAINT "MovimentoPontos_pedidoId_fkey" FOREIGN KEY ("pedidoId") REFERENCES "Pedido"("id"));
CREATE TABLE IF NOT EXISTS "ConsentimentoLgpd" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "usuarioId" INTEGER NOT NULL, "finalidade" TEXT NOT NULL, "concedido" BOOLEAN NOT NULL, "registradoEm" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ConsentimentoLgpd_usuarioId_fkey" FOREIGN KEY ("usuarioId") REFERENCES "Usuario"("id"));
